  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly attributes a positive outcome, action, or achievement to their own efforts, advocacy, or legislative work in a public statement or press release.",
    "clarification": "Credit-claiming is identified when the senator uses first-person language (e.g., 'I secured,' 'I authored,' 'I fought for') or explicitly ties a positive result to their direct involvement. This includes announcing funding they helped secure, legislation they introduced or co-sponsored, or outcomes they influenced through advocacy. The focus is on the senator taking personal or direct responsibility for a tangible benefit or action.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states that he authored legislation that created the National Center designation for Bismarck State College and takes pride in the program's achievements. This is a clear example of credit-claiming, as he directly ties the outcome to his legislative work."
      },
      {
        "document_id": "3482",
        "explanation": "Sens. Mikulski and Cardin announce federal funding for firefighters and explicitly state that Sen. Mikulski fights each year to increase funding for the program. This demonstrates credit-claiming by linking the funding to her advocacy efforts."
      },
      {
        "document_id": "4585",
        "explanation": "Senator Schumer announces federal fire grants and states that he pushed for additional funding for the Assistance to Firefighters Grant Program. This is credit-claiming as he directly attributes the outcome to his efforts."
      }
    ],
    "negative_clarification": "Credit-claiming does NOT occur when a senator merely discusses an issue, criticizes others, or provides general support without explicitly tying a positive outcome to their own actions. Statements that are purely informational, critical, or expressive of general support (without claiming personal responsibility) do not qualify as credit-claiming. Additionally, routine legislative duties (e.g., voting, co-sponsoring without explicit claims) or general advocacy without a clear link to a specific outcome are not considered credit-claiming.",
    "negative_examples": [
